import { RAW_VARIABLE } from './command.ts'

/**
 * The note the model reads at the session's start, after /clear and after a compaction, so it knows a
 * condensed result is complete and how to reach every byte.
 */
export const AWARENESS = [
  'Bash results in this session pass through a filter that condenses known commands (git, test runners, linters, compilers, package managers, containers, file listings and searches): passing tests collapse to a count, progress and noise lines drop, long lists end with a count of the rest.',
  'Treat a condensed result as complete. A result that left something out ends with `[full output: <path>]`; open that file with the Read tool when you need what was left out.',
  'Claude Code cuts a failed command\'s output at 10000 characters before any filter reads it; such a result ends with `[output cut by Claude Code ...]`, and its middle exists nowhere, so run the command again with narrower output when you need it.',
  `When you need the exact bytes (a patch to apply, output to parse), prefix the command with \`${RAW_VARIABLE}=1\`, and the result comes back unfiltered.`,
].join(' ')

export const USAGE = 'expects nothing (the status), on, off, exclude <prefix | ^regex>, include <prefix | ^regex>, excludes, filters, trust, untrust, gain [project | daily | graph | history], discover [days] [all], learn [days] [write] or cost'

/** A rule file as the person reads it, and the names of its rules. */
export type RuleFileView = { shown: string; source: 'project' | 'global'; exists: boolean; trusted: boolean; names: string[] }

/** `/bash-diet filters`: every rule file with its state and rules, then the built-in rules. */
export function filtersText(files: RuleFileView[], builtin: string[]): string {
  const rows = files.map(f => {
    if (!f.exists) return `${f.source}: ${f.shown} (none)`
    const state = f.source === 'project' && !f.trusted ? ' (not trusted: /bash-diet trust runs it)' : ''
    return `${f.source}: ${f.shown}${state}: ${f.names.length === 0 ? 'no rules' : f.names.join(', ')}`
  })
  return [...rows, `built-in: ${builtin.join(', ')}`].join('\n')
}

/** Characters per token, as the gain is estimated: no tokenizer runs here. */
export const CHARS_PER_TOKEN = 4

export function tokensOf(chars: number): number {
  return Math.ceil(chars / CHARS_PER_TOKEN)
}

/** A token or character count as `830`, `12.4k` or `1.2M`. */
export function fmtTokens(n: number): string {
  if (n < 1000) return String(n)
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 10_000 ? 1 : 0)}k`
  return `${(n / 1_000_000).toFixed(1)}M`
}

/** The share of the characters the filter took out, as `(−57%)`. */
function pctText(rawChars: number, shownChars: number): string {
  const pct = rawChars === 0 ? 0 : Math.round(((rawChars - shownChars) / rawChars) * 100)
  return `(−${pct}%)`
}

/** The tokens saved as estimated from the characters: `~23k tokens estimated`. */
function estimateText(rawChars: number, shownChars: number): string {
  return `~${fmtTokens(tokensOf(rawChars - shownChars))} tokens estimated`
}

/** The measured characters before and after: `164k → 71k chars (−57%)`. */
export function charsText(rawChars: number, shownChars: number): string {
  return `${fmtTokens(rawChars)} → ${fmtTokens(shownChars)} chars ${pctText(rawChars, shownChars)}`
}

/** The measured characters, then the tokens saved as estimated from them. */
export function savingText(rawChars: number, shownChars: number): string {
  return `${charsText(rawChars, shownChars)} · ${estimateText(rawChars, shownChars)}`
}

/** The session's gain: how many results shrank and what they saved. */
export function sessionText(calls: number, rawChars: number, shownChars: number): string {
  if (calls === 0) return 'no Bash result shrunk yet'
  return `${calls} result(s) shrunk · ${savingText(rawChars, shownChars)}`
}

/** How the sidebar colours a line or a part of one. */
type Tone = 'ok' | 'warn' | 'error' | 'dim'
export type Part = { text: string; kind?: Tone }
/** A sidebar line; `parts` colour pieces of it, and `text` holds the whole line for a sidebar that draws no parts. */
export type Line = { text: string; kind?: Tone; parts?: Part[] }

const part = (text: string, kind: Tone | undefined): Part => (kind === undefined ? { text } : { text, kind })

/** A line made of parts, its `text` their texts joined. */
const partsLine = (parts: Part[]): Line => ({ text: parts.map(p => p.text).join(''), parts })

/**
 * `sessionText` as the sidebar line: faint before any result shrank, then the share taken out green and
 * the token estimate faint, the counts in the default colour.
 */
export function sessionLine(calls: number, rawChars: number, shownChars: number): Line {
  if (calls === 0) return { text: sessionText(calls, rawChars, shownChars), kind: 'dim' }
  return partsLine([
    part(`${calls} result(s) shrunk · ${fmtTokens(rawChars)} → ${fmtTokens(shownChars)} chars `, undefined),
    part(pctText(rawChars, shownChars), 'ok'),
    part(' · ', undefined),
    part(estimateText(rawChars, shownChars), 'dim'),
  ])
}

export function statusText(enabled: boolean, excludes: string[], session: string): string {
  const ex = excludes.length === 0 ? '' : ` · ${excludes.length} exclude(s)`
  return `${enabled ? 'on' : 'off'}${ex} · ${session}`
}

/** Whether a pattern is a valid exclude: a plain prefix, or a `^` regex that compiles. */
export function patternError(pattern: string): string | undefined {
  if (pattern === '') return 'expects a command prefix or a ^regex'
  if (!pattern.startsWith('^')) return undefined
  try {
    new RegExp(pattern)
    return undefined
  } catch (err) {
    return `not a valid regex: ${err instanceof Error ? err.message : String(err)}`
  }
}

/**
 * Whether an exclude matches a command: a plain pattern matches the command's words from the start at a
 * word boundary (`npm` matches `npm test`, not `npmx`), a `^` pattern is a regex over the same words.
 */
export function isExcluded(patterns: string[], words: string[]): boolean {
  const text = words.join(' ')
  return patterns.some(p => {
    if (p.startsWith('^')) return new RegExp(p).test(text)
    return text === p || text.startsWith(`${p} `)
  })
}

files.hooks/shell.ts:
/**
 * Reads a Bash command the way a shell splits it, far enough to know which command's output the model
 * will read. Nothing here runs a command. A construct whose output this reading cannot attribute to one
 * command (a heredoc, a command substitution, a subshell, a process substitution, `|&`) makes the whole
 * command opaque, and an opaque command is never filtered.
 */

/** One word or operator of a command, with its place in the text; a word's text is unquoted. */
export type Token = { kind: 'word' | 'op'; text: string; start: number; end: number }

/** One redirect of a stage: the operator with its file descriptor prefix, and the word after it. */
export type Redirect = { op: string; target: string }

/** One command of a pipeline: its words and its redirects. */
export type Stage = { words: Token[]; redirects: Redirect[] }

/** A list of stages joined by `|`, ended by `&&`, `||`, `;`, `&` or the end of the text. */
export type Segment = { stages: Stage[]; background: boolean }

export type Parsed = { segments: Segment[]; opaque: boolean }

/** Longest first, so `&&` is read before `&`. */
const OPS = ['&&', '||', '|&', '>>', '<<', '>&', '&>', '<(', '>(', ';', '|', '&', '<', '>', '(', ')']
const OPAQUE_OPS = new Set(['|&', '<<', '<(', '>(', '(', ')'])
const SEPARATORS = new Set(['&&', '||', ';', '&'])

type Lex = { src: string; i: number; tokens: Token[]; word: string; wordStart: number; opaque: boolean }

/** Splits a command into words and operators; `opaque` when a construct hides where output comes from. */
export function lex(src: string): { tokens: Token[]; opaque: boolean } {
  const s: Lex = { src, i: 0, tokens: [], word: '', wordStart: -1, opaque: false }
  while (s.i < src.length && !s.opaque) step(s)
  flush(s)
  return { tokens: s.tokens, opaque: s.opaque }
}

const opaque = (s: Lex): void => { s.opaque = true }
const blank = (s: Lex): void => { flush(s); s.i += 1 }

/** The characters that start something other than a plain word character. */
const HANDLERS: Record<string, (s: Lex) => void> = {
  "'": single, '"': double, '\\': escape, '`': opaque, '\n': newline, ' ': blank, '\t': blank,
}

function step(s: Lex): void {
  const c = s.src[s.i] ?? ''
  const handler = HANDLERS[c]
  if (handler !== undefined) return handler(s)
  if (c === '$' && s.src[s.i + 1] === '(') return opaque(s)
  if (c === '#' && s.wordStart < 0) return comment(s)
  if ('&|;<>()'.includes(c)) return operator(s)
  add(s, c, 1)
}

function add(s: Lex, text: string, length: number): void {
  if (s.wordStart < 0) s.wordStart = s.i
  s.word += text
  s.i += length
}

function flush(s: Lex): void {
  if (s.wordStart < 0) return
  s.tokens.push({ kind: 'word', text: s.word, start: s.wordStart, end: s.i })
  s.word = ''
  s.wordStart = -1
}

function single(s: Lex): void {
  const close = s.src.indexOf("'", s.i + 1)
  if (close < 0) { s.opaque = true; return }
  add(s, s.src.slice(s.i + 1, close), close + 1 - s.i)
}

/** A double-quoted part: `\` escapes only `"`, `\`, `$` and a backtick; `$(` or a backtick inside is opaque. */
function double(s: Lex): void {
  let j = s.i + 1
  let text = ''
  while (j < s.src.length && s.src[j] !== '"') {
    const part = quotedChar(s.src, j)
    if (part === undefined) return opaque(s)
    text += part.text
    j += part.length
  }
  if (j >= s.src.length) return opaque(s)
  add(s, text, j + 1 - s.i)
}

/** One character inside double quotes and how many it took, or undefined for a substitution. */
function quotedChar(src: string, j: number): { text: string; length: number } | undefined {
  const c = src[j] ?? ''
  const after = src[j + 1] ?? ''
  if (c === '`' || (c === '$' && after === '(')) return undefined
  const escaped = c === '\\' && '"\\$`'.includes(after)
  return escaped ? { text: after, length: 2 } : { text: c, length: 1 }
}

/** A backslash keeps the next character; before a newline it joins the two lines. */
function escape(s: Lex): void {
  const next = s.src[s.i + 1] ?? ''
  if (next === '\n') { s.i += 2; return }
  add(s, next, 2)
}

function comment(s: Lex): void {
  const end = s.src.indexOf('\n', s.i)
  s.i = end < 0 ? s.src.length : end
}

/** A newline ends a command as `;` does. */
function newline(s: Lex): void {
  flush(s)
  s.tokens.push({ kind: 'op', text: ';', start: s.i, end: s.i + 1 })
  s.i += 1
}

/** An operator; digits right before `<` or `>` are its file descriptor (`2>&1`), not a word. */
function operator(s: Lex): void {
  const c = s.src[s.i] ?? ''
  const fd = s.wordStart >= 0 && /^\d+$/.test(s.word) && (c === '<' || c === '>') ? s.word : ''
  const start = fd === '' ? s.i : s.wordStart
  if (fd === '') flush(s)
  else { s.word = ''; s.wordStart = -1 }
  const op = OPS.find(o => s.src.startsWith(o, s.i)) ?? c
  if (OPAQUE_OPS.has(op)) { s.opaque = true; return }
  s.i += op.length
  s.tokens.push({ kind: 'op', text: fd + op, start, end: s.i })
}

/** Groups the tokens into segments and stages; a redirect takes the word after it. */
export function parse(src: string): Parsed {
  const { tokens, opaque } = lex(src)
  const segments: Segment[] = []
  let segment: Segment = { stages: [{ words: [], redirects: [] }], background: false }
  for (let i = 0; i < tokens.length; i += 1) {
    const t = tokens[i] as Token
    const stage = segment.stages[segment.stages.length - 1] as Stage
    if (t.kind === 'word') stage.words.push(t)
    else if (t.text === '|') segment.stages.push({ words: [], redirects: [] })
    else if (SEPARATORS.has(t.text)) {
      segment.background = t.text === '&'
      segments.push(segment)
      segment = { stages: [{ words: [], redirects: [] }], background: false }
    } else {
      stage.redirects.push({ op: t.text, target: tokens[i + 1]?.text ?? '' })
      i += 1
    }
  }
  segments.push(segment)
  return { segments: segments.filter(g => g.stages.some(st => st.words.length > 0)), opaque }
}

/**
 * Whether a redirect sends standard output away from the result: into a file, not to /dev/null or to
 * another descriptor. `2>err.log` leaves stdout where it was.
 */
export function hidesStdout(r: Redirect): boolean {
  if (!r.op.includes('>')) return false
  if (r.target === '/dev/null') return false
  if (r.op.startsWith('&')) return true
  const fd = /^\d*/.exec(r.op)?.[0] || '1'
  return fd === '1' && !r.op.endsWith('&')
}

/** A word that sets a variable for the command after it: `FOO=bar`. */
export function isAssignment(word: string): boolean {
  return /^[A-Za-z_][A-Za-z0-9_]*=/.test(word)
}

files.hooks/rules.ts:
/**
 * Names the command a filter answers for: `npx tsc`, `python3 -m pytest`, `./gradlew`, `git -C dir
 * status` and `/usr/bin/git status` all read as the tool and subcommand the filter tables are keyed by.
 */

/** A classified command: the tool, its subcommand when the tool has them, and the arguments after. */
export type Classified = {
  tool: string
  sub: string
  args: string[]
  /** The index, in the words handed in, of the last word of the name (`test` in `go test`). */
  nameEnd: number
}

/** Tools whose first argument is a subcommand the filters tell apart. */
const SUBCOMMAND_TOOLS = new Set([
  'git', 'yadm', 'gh', 'glab', 'gt', 'cargo', 'go', 'npm', 'pnpm', 'bun', 'deno', 'docker', 'kubectl', 'oc',
  'aws', 'helm', 'terraform', 'tofu', 'pulumi', 'pip', 'pip3', 'uv', 'poetry', 'ruff', 'sqlfluff', 'dotnet',
  'mvn', 'mvnd', 'gradle', 'gradlew', 'sbt', 'bundle', 'rake', 'rails', 'artisan', 'golangci-lint', 'next',
  'prisma', 'playwright', 'brew', 'composer', 'mix', 'swift', 'systemctl', 'gcloud', 'pio', 'pre-commit',
  'trunk', 'quarto', 'shopify', 'liquibase', 'ansible-playbook', 'fail2ban-client', 'yarn', 'phpstan',
])

/** Runners that start another tool: the words they take before it. */
const RUNNERS: Record<string, (words: string[]) => number> = {
  npx: w => 1 + optionCount(w, 1),
  bunx: w => 1 + optionCount(w, 1),
  pnpx: w => 1 + optionCount(w, 1),
  pnpm: w => (['exec', 'dlx'].includes(w[1] ?? '') ? 2 : 0),
  npm: w => (['exec', 'x'].includes(w[1] ?? '') ? 2 + optionCount(w, 2) : 0),
  uv: w => (w[1] === 'run' ? 2 + optionCount(w, 2) : 0),
  poetry: w => (w[1] === 'run' ? 2 : 0),
  pipenv: w => (w[1] === 'run' ? 2 : 0),
  bundle: w => (w[1] === 'exec' ? 2 : 0),
  python: w => (w[1] === '-m' ? 2 : 0),
  python3: w => (w[1] === '-m' ? 2 : 0),
  php: w => (w[1] === 'artisan' ? 1 : 0),
}

/** Git's options before the subcommand; the ones in `TAKES_VALUE` take the next word as well. */
const GIT_TAKES_VALUE = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace'])

/** A file name with its directory and a Windows or wrapper suffix dropped: `./gradlew.bat` is `gradlew`. */
export function baseName(word: string): string {
  const name = word.split(/[\\/]/).pop() ?? word
  return name.replace(/\.(exe|bat|cmd)$/i, '').replace(/^mvnw$/, 'mvn')
}

function optionCount(words: string[], from: number): number {
  let n = 0
  while (from + n < words.length && (words[from + n] ?? '').startsWith('-')) n += 1
  return n
}

/** The index of the tool's own name after every runner: `npx --yes tsc` is `tsc` at 2. */
function toolIndex(words: string[]): number {
  let at = 0
  for (let guard = 0; guard < 4; guard += 1) {
    const runner = RUNNERS[baseName(words[at] ?? '')]
    const n = runner === undefined ? 0 : runner(words.slice(at))
    if (n === 0 || at + n >= words.length) return at
    at += n
  }
  return at
}

/** The index of git's subcommand after its global options. */
function gitSubIndex(words: string[], at: number): number {
  let i = at + 1
  while (i < words.length && (words[i] ?? '').startsWith('-')) {
    const word = words[i] ?? ''
    i += GIT_TAKES_VALUE.has(word) ? 2 : 1
  }
  return i
}

/** The index of the subcommand: the first word after the tool that is not an option. */
function subIndex(tool: string, words: string[], at: number): number {
  if (tool === 'git' || tool === 'yadm') return gitSubIndex(words, at)
  let i = at + 1
  while (i < words.length && (words[i] ?? '').startsWith('-')) i += 1
  return i
}

/** Reads the tool and subcommand of a command's words, or undefined for no words. */
export function classify(words: string[]): Classified | undefined {
  if (words.length === 0) return undefined
  const at = toolIndex(words)
  const tool = baseName(words[at] ?? '')
  if (!SUBCOMMAND_TOOLS.has(tool)) return { tool, sub: '', args: words.slice(at + 1), nameEnd: at }
  const s = subIndex(tool, words, at)
  if (s >= words.length) return { tool, sub: '', args: words.slice(at + 1), nameEnd: at }
  return { tool, sub: words[s] ?? '', args: [...words.slice(at + 1, s), ...words.slice(s + 1)], nameEnd: s }
}

files.hooks/filters/generic.ts:
import { collapseBlanks, collapseRepeats, linesOf, type Filter, type FilterResult } from './common.ts'

/**
 * The filter for a command no table names, and for a chain of several commands: it removes terminal
 * escapes and progress redraws, folds repeated lines into one with a count, and keeps one blank line of
 * each run. It drops no line of content, so it needs no full-output file.
 */
export function cleanup(text: string): FilterResult {
  return { text: collapseBlanks(collapseRepeats(linesOf(text))).join('\n'), elided: false }
}

export const GENERIC: Filter = { run: ({ text }) => cleanup(text) }

